<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\{AdminPermission,User};use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class PermissionController extends Controller {public function index(){return view('admin.legacy.permissions',['permissions'=>AdminPermission::orderBy('group')->orderBy('name')->get(),'admins'=>User::where('role','admin')->orderBy('full_name')->get(),'assigned'=>DB::table('admin_permission_user')->get()->groupBy('user_id')]);}public function store(Request $r){if($r->input('action')==='permission'){AdminPermission::firstOrCreate(['key'=>$r->validate(['key'=>'required|max:100'])['key']],['name'=>$r->validate(['name'=>'required|max:255'])['name'],'group'=>$r->input('group')]);}else{$d=$r->validate(['user_id'=>'required|exists:users,id','permissions'=>'nullable|array']);DB::table('admin_permission_user')->where('user_id',$d['user_id'])->delete();foreach($d['permissions']??[] as $p)DB::table('admin_permission_user')->insert(['user_id'=>$d['user_id'],'permission_id'=>(int)$p]);}return back()->with('ok','Права сохранены');}}
